@startuml

class HospitalHouseMD {
  + Name : string
}

class Patient {
  + Name : string
  + Symptoms : string
}

class Doctor {
  + Name : string
  + PractitionerNumber : int
}

class Diagnosis {
  + Description : string
  + IsApproved : boolean
}

class Treatment {
  + Name : string
  + Description : string
  + CurrentStage : int
}

class ConsentForm {
  + Signature : string
  + DateSigned : date
  + IsRetracted : boolean
}

class Illness {
  + Name : string
  + PriorityScore : PriorityScore
}

enum PriorityScore {
  High
  Low
}

class TreatmentDatabase {
  + ID : int
}

class Nurse {
  + Name : string
}

HospitalHouseMD "1" *-- "1..*" Patient
Patient "1" -- "1..*" Doctor
Doctor "1" -- "0..*" Diagnosis
Patient "1" -- "0..*" Diagnosis
Diagnosis "1" -- "1" Illness
Illness "1" -- "0..*" Diagnosis
HospitalHouseMD "1" *-- "1" TreatmentDatabase
TreatmentDatabase "1" -- "*" Treatment
Diagnosis "1" -- "1..*" Treatment
Patient "1" -- "0..*" ConsentForm
ConsentForm "1" -- "0..*" Treatment
Patient "1" -- "0..*" Nurse
Treatment "1" -- "0..*" Nurse
Doctor "1" -- "0..*" Treatment

@enduml

